// prime detection
bool isPrime(int n) {
    if (n < 2) return false;
    if ((n&1) == 0) return false;

    for (int i = 3; i*i <= n; i += 2)
        if (n%i == 0) return false;

    return true;
}

// coloring
vec4 col(vec2 pos) {
    vec2 t = pos/iResolution.xy;

    return vec4(
        cos(t.x),
        sin(t.y*1.5),
        cos((t.x+t.y)*.3),
        1.
    )*.5 + .5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // selecting a prime (pos + scrolling)
    float x = fragCoord.x;
    float y = (iResolution.y-fragCoord.y-1.) + floor(iTime*300.);
    int i = int(x + iResolution.x*y);

    if (isPrime(i)) fragColor = col(vec2(x, y));
    else fragColor = vec4(0., 0., 0., 1.);
}
